.signal-audit{position:relative;isolation:isolate;overflow:hidden;width:min(100%,720px);border:1px solid var(--border);border-radius:var(--surface-radius);background:var(--card);color:var(--card-foreground);padding:24px}
.signal-audit__orbit{position:absolute;z-index:-1;top:-86px;right:-48px;width:300px;height:300px;border:1px solid color-mix(in srgb,var(--foreground) 9%,transparent);border-radius:50%;box-shadow:0 0 0 48px color-mix(in srgb,var(--foreground) 2.5%,transparent),0 0 0 96px color-mix(in srgb,var(--foreground) 1.5%,transparent)}
.signal-audit__orbit:before,.signal-audit__orbit:after{content:"";position:absolute;inset:50%;background:color-mix(in srgb,var(--foreground) 8%,transparent);transform:translate(-50%,-50%)}
.signal-audit__orbit:before{width:1px;height:100%}.signal-audit__orbit:after{width:100%;height:1px}
.signal-audit__orbit span{position:absolute;left:50%;top:50%;width:10px;height:10px;border-radius:50%;background:var(--primary);transform:translate(-50%,-50%)}
.signal-audit__header,.signal-audit__footer,.signal-audit__metric>div:first-child{display:flex;align-items:center;justify-content:space-between;gap:16px}
.signal-audit__header{position:relative;z-index:1;font-size:12px}.signal-audit__live{display:flex;align-items:center;gap:9px}.signal-audit__live i{width:7px;height:7px;border-radius:50%;background:var(--primary)}.signal-audit__status{color:var(--accent);font-size:11px;letter-spacing:.16em;text-transform:uppercase}
.signal-audit__score{margin:68px 0 28px}.signal-audit__label{color:var(--muted-foreground);font-size:11px;font-weight:var(--label-weight);letter-spacing:.18em;text-transform:uppercase}.signal-audit__score strong{display:block;margin-top:8px;font-size:72px;font-weight:300;line-height:.88;letter-spacing:-.06em}.signal-audit__score small{margin-left:4px;color:var(--primary);font-size:24px;font-weight:400}
.signal-audit__metrics{display:grid;gap:17px}.signal-audit__metric{font-size:13px}.signal-audit__metric b{font-weight:500}.signal-audit__track{height:4px;margin-top:8px;background:color-mix(in srgb,var(--foreground) 11%,transparent)}.signal-audit__track i{display:block;height:100%;background:var(--primary);transition:width var(--motion-duration) var(--motion-easing)}.signal-audit__track i.is-accent{background:var(--accent)}.signal-audit__track i.is-neutral{background:color-mix(in srgb,var(--foreground) 76%,transparent)}
.signal-audit__insights{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:24px}.signal-audit__insights>div{min-width:0;border:1px solid var(--border);padding:16px}.signal-audit__insights p{margin:8px 0 0;color:var(--muted-foreground);font-size:15px}
.signal-audit__footer{margin-top:24px;padding-top:20px;border-top:1px solid var(--border)}.signal-audit__footer>span{font-size:16px}
@media(max-width:520px){.signal-audit{padding:18px}.signal-audit__orbit{top:-58px;right:-74px;width:230px;height:230px}.signal-audit__score{margin-top:50px}.signal-audit__score strong{font-size:62px}.signal-audit__insights{grid-template-columns:1fr}.signal-audit__footer{align-items:center}}
